head.script:
scwin.onpageload = function() {
    localStorage.setItem('log', "wframe_toto.xml onpageload");
    console.log("wframe_toto.xml onpageload");
};
scwin.onpageunload = function() {};
scwin.checkVal = function() {
    //alert(localStorage.getItem('log'))
    return localStorage.getItem('log') == "wframe_toto.xml onpageloadtabControl_toto.xml onpageloadWebSquare.xml onpageload";
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop

    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
localStorage.removeItem('log');
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //localStorage.removeItem('log');
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }

}
